#[wasm_bindgen]
pub fn flood_fill(buf: &mut [u8], w: u32, h: u32, x: u32, y: u32, color: u32) {
    let target = read_px(buf, w, x, y);
    if target == color { return; }
    let mut stack = vec![(x, y)];
    while let Some((cx, cy)) = stack.pop() {
        if read_px(buf, w, cx, cy) != target { continue; }
        write_px(buf, w, cx, cy, color);
        push_neighbors(&mut stack, cx, cy, w, h);
    }
}

